@namespace sv_116d9b393d2f4ee9af2f7eccf36b19a4.Components.Pages.Apply

<h4 class="mb-3">Cover Letter</h4>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Write your cover letter</label>
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
        @bind="coverLetterValue" @bind:event="oninput"
        placeholder="Tell us why you're a great fit for this role..."></textarea>
    <div class="form-text text-end">
        @(coverLetterValue?.Length ?? 0) / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? errorMessage;

    private string coverLetterValue
    {
        get => CoverLetter;
        set
        {
            CoverLetter = value;
            CoverLetterChanged.InvokeAsync(value);
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            errorMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

